module oven_decision (\n    input [9:0] n,\n    input [9:0] t,\n    input [9:0] k,\n    input [9:0] d,\n    output reg reason\n);\n    wire [10:0] adj_n = n + k - 1'd1;  // n + k - 1\n    wire [9:0] batches = adj_n / k;    // ceil(n/k)\n    wire [9:0] batches_minus1 = batches - 1'd1;\n    wire [19:0] threshold = batches_minus1 * t;\n    always @(*) begin\n        reason = (d < threshold) ? 1'b1 : 1'b0;\n    end\nendmodule